export type IconName = string;

/** Inline SVG markup for an icon, tintable via CSS `color`. Empty string if unknown. */
export function icon(name: string, cls = ''): string {
  const p = PATHS[name];
  if (!p) return '';
  const c = cls ? ` ${cls}` : '';
  return `<svg class="ico${c}" viewBox="0 0 512 512" fill="currentColor" aria-hidden="true" focusable="false">${p}</svg>`;
}

export const ICON_NAMES = Object.keys(PATHS);
